from itertools import product
# Try interpretation: c[k] is C_k with c indexed from... 
# Option A: c[6]=C_6, c[9]=C_9
# Option B: 0-indexed, c[6]=C_7, c[9]=C_10
# Try seq 0-indexed vs 1-indexed too
# seq[1]=1 - could be 0-indexed (second elem) or 1-indexed (first)

for seqidx in ['0','1']:
    for cidx in ['0','1']:
        results=[]
        for bits in product([-1,1], repeat=11):
            if seqidx=='0':
                if bits[1]!=1 or bits[8]!=1: continue
            else:
                if bits[0]!=1 or bits[7]!=1: continue
            c = [sum(bits[i]*bits[i+k] for i in range(11-k)) for k in range(1,11)]
            # c[0]=C_1...c[9]=C_10
            if cidx=='0':
                if c[6]!=0 or c[9]!=1: continue
            else:
                if c[5]!=0 or c[8]!=1: continue
            s = sum(x*x for x in c)
            if s<=23:
                results.append((s,list(bits),c))
        print(f"seqidx={seqidx}, cidx={cidx}: {len(results)} solutions")
        if results:
            results.sort()
            print(results[0])
